const expandedSeeds = [...seeds, ...gapSeeds]

export const pipExpansionQuestions: CatQuestion[] = expandedSeeds.map((seed, index) => {
  const correctIndex = index % 5
  const distractors = [...seed.distractors]
  if (distractors.length === 3) distractors.push("Tidak ada jawaban yang sesuai")
  const options = distractors
  options.splice(correctIndex, 0, seed.answer)
  return {
    id: `pip-${String(1040 + index).padStart(4, "0")}`,
    type: "pip",
    category: seed.category,
    question: seed.question,
    options: options as CatQuestion["options"],
    correctIndex,
    explanation: `${seed.explanation} (Acuan: ${seed.source}, Buku Pendidikan Pancasila Kelas X, edisi revisi 2023.)`,
    status: "active",
  }
})
